"""Authenticated tenant members may read their own invoices."""
INVOICES = {
    "inv-a": {"tenant_id": "tenant-a", "total_cents": 1700},
    "inv-b": {"tenant_id": "tenant-b", "total_cents": 9200},
}


def get_invoice(principal, invoice_id):
    if not principal.get("authenticated"):
        raise PermissionError("Authentication required")
    if not principal.get("tenant_id"):
        raise PermissionError("Tenant membership required")
    invoice = INVOICES.get(invoice_id)
    if invoice is None:
        return None
    return dict(invoice)

